-- Version history: add the 2.1.0 entry (trade value) once. Idempotent: skipped if a 2.1.0 entry exists.
INSERT INTO "site_config" ("key", "value")
VALUES ('changelog', $cl$[{"date":"2026-10-10T22:00:00.000Z","title":"Trade value","version":"2.1.0","description":"Every trade now has a value: how many points the players and picks that moved went on to score.\n\n**Trade Value page**\n- New page under Transactions: pick a manager and see every trade they made that season, with each player and pick broken down week by week (points, and who had him).\n- Changing the season keeps the same manager selected.\n- Summary for the season: trades, value received, value sent away, net value and net per trade.\n\n**How trades are valued**\n- A player is worth the points he scored from the trade to the end of that season, wherever he was. A later flip or drop never changes it, so a trade is not judged on what the other manager did next.\n- In dynasty, the next season also counts, at half. A draft pick is worth the player it became, or the average for its round before the draft.\n- Points for players nobody rostered now come from Sleeper's stats, scored with each league's own settings.\n- ESPN seasons (2020 and 2021) have no stats, so they count only the points a player scored while on a roster. They are labelled \"roster-only points\".\n\n**Records**\n- New manager records under Transactions: Best overall trade value and Best average trade value.\n- New trade records on the Overall page: Best trade and Most lopsided trade by estimated value. Trade records now also show who the other managers were and what each side gave.\n\n**Transactions page and franchise pages**\n- Each side of a trade shows its estimated trade value, and each player and pick shows his share. Trade cards show the manager on each side.\n- A franchise page now lists all of its transactions for a chosen season.\n- Team dropdowns across the site read \"Manager · Team\".\n\n**Fixes**\n- Pages scroll back to the top when you change page.\n- The Transactions menu no longer highlights Trades & Waivers while you are on Trade Value.\n- Two trades the commissioner reversed and the managers then repeated are no longer counted twice."}]$cl$::jsonb)
ON CONFLICT ("key") DO UPDATE
  SET "value" = EXCLUDED."value" || "site_config"."value", "updated_at" = now()
  WHERE NOT ("site_config"."value" @> '[{"version": "2.1.0"}]'::jsonb);
